import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

export default function TeacherDashboard() {
  const { user, logout, API } = useAuth();
  const navigate = useNavigate();
  const [subject, setSubject] = useState('');
  const [qrCode, setQrCode] = useState(null);
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [countdown, setCountdown] = useState(0);
  const [autoRenew, setAutoRenew] = useState(false);
  const [pastSessions, setPastSessions] = useState([]);
  const [loadingSessions, setLoadingSessions] = useState(false);
  const timerRef = useRef(null);
  const autoRenewRef = useRef(false);

  // Keep ref in sync
  autoRenewRef.current = autoRenew;

  // ── Fetch session history ─────────────────────
  const fetchSessions = useCallback(async () => {
    setLoadingSessions(true);
    try {
      const res = await API.get('/qr/sessions');
      setPastSessions(res.data.sessions || []);
    } catch {
      // silently fail
    } finally {
      setLoadingSessions(false);
    }
  }, [API]);

  useEffect(() => { fetchSessions(); }, [fetchSessions]);

  // ── Generate QR ───────────────────────────────
  const generateQR = useCallback(async () => {
    if (!subject.trim()) return;
    setLoading(true);
    setError('');
    try {
      const res = await API.post('/qr/generate', { subject: subject.trim() });
      setQrCode(res.data.qr);
      setSession(res.data.session);
      startCountdown(res.data.session.ttlSeconds);
      fetchSessions();
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to generate QR');
    } finally {
      setLoading(false);
    }
  }, [subject, API, fetchSessions]);

  // ── Start countdown ───────────────────────────
  const startCountdown = (seconds) => {
    if (timerRef.current) clearInterval(timerRef.current);
    setCountdown(seconds);
    timerRef.current = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(timerRef.current);
          timerRef.current = null;
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  // ── Auto-regenerate on expiry ─────────────────
  useEffect(() => {
    if (countdown === 0 && autoRenewRef.current && subject.trim() && session) {
      const t = setTimeout(() => generateQR(), 300);
      return () => clearTimeout(t);
    }
  }, [countdown, subject, session, generateQR]);

  // ── End session ───────────────────────────────
  const endSession = async () => {
    if (!session) return;
    try {
      await API.put('/qr/end', { sessionId: session.sessionId });
      setQrCode(null);
      setSession(null);
      setCountdown(0);
      if (timerRef.current) clearInterval(timerRef.current);
      setAutoRenew(false);
      fetchSessions();
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to end session');
    }
  };

  // ── Cleanup ───────────────────────────────────
  useEffect(() => {
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, []);

  const handleLogout = () => { logout(); navigate('/login'); };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <div>
          <h1>👨‍🏫 Teacher Dashboard</h1>
          <span style={styles.roleBadge}>{user?.role}</span>
        </div>
        <div>
          <span style={styles.userInfo}>{user?.name}</span>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
        </div>
      </div>

      <div style={styles.grid}>
        {/* ── Left Column: QR Generation ── */}
        <div style={styles.leftCol}>
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>🎯 Generate QR Code</h2>
            <form onSubmit={(e) => { e.preventDefault(); generateQR(); }} style={styles.form}>
              <input
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                placeholder="Subject (e.g., Mathematics)"
                style={styles.input}
                required
              />
              <button type="submit" disabled={loading} style={styles.button}>
                {loading ? '⏳ Generating...' : qrCode ? '🔄 Generate New' : '🚀 Generate QR'}
              </button>
            </form>
            {error && <div style={styles.error}>{error}</div>}
          </div>

          {/* ── Active QR Display ── */}
          {qrCode && session && (
            <div style={styles.card}>
              <div style={styles.qrHeader}>
                <h2 style={styles.cardTitle}>📸 Active QR</h2>
                <div style={styles.badge}>LIVE</div>
              </div>
              <div style={styles.qrContainer}>
                <img src={qrCode} alt="QR" style={styles.qrImage} />
              </div>
              <p style={styles.sessionInfo}>
                <strong>{session.subject}</strong>
              </p>
              <p style={styles.timer}>
                Expires in{' '}
                <span style={{ color: countdown < 10 ? '#ff6b6b' : '#6c63ff', fontWeight: 'bold', fontSize: '1.2rem' }}>
                  {countdown}s
                </span>
              </p>
              <p style={{ fontSize: '0.7rem', color: '#666', fontFamily: 'monospace' }}>
                {session.sessionId.slice(0, 20)}...
              </p>

              {/* Auto-renew toggle */}
              <div style={styles.toggleRow}>
                <label style={styles.switch}>
                  <input type="checkbox" checked={autoRenew} onChange={() => setAutoRenew((p) => !p)} />
                  <span style={styles.slider}></span>
                </label>
                <span style={{ fontSize: '0.85rem', color: '#ccc' }}>Auto-renew on expiry</span>
              </div>

              <button onClick={endSession} style={styles.endBtn}>🛑 End Session</button>
            </div>
          )}

          {/* ── Quick info when idle ── */}
          {!qrCode && (
            <div style={styles.card}>
              <h2 style={styles.cardTitle}>ℹ️ How it works</h2>
              <ol style={{ color: '#aaa', lineHeight: '2', paddingLeft: '20px', fontSize: '0.9rem' }}>
                <li>Enter subject → <strong>Generate QR</strong></li>
                <li>Students scan the QR to mark attendance</li>
                <li>GPS location is verified automatically</li>
                <li>Enable <strong>Auto-renew</strong> for continuous sessions</li>
                <li>Use <strong>End Session</strong> to stop early</li>
              </ol>
            </div>
          )}
        </div>

        {/* ── Right Column: Session History ── */}
        <div style={styles.rightCol}>
          <div style={styles.card}>
            <h2 style={styles.cardTitle}>📊 Session History</h2>
            {loadingSessions ? (
              <p style={{ color: '#888' }}>Loading sessions...</p>
            ) : pastSessions.length === 0 ? (
              <p style={{ color: '#888' }}>No sessions yet. Generate your first QR above.</p>
            ) : (
              <div style={styles.sessionList}>
                {pastSessions.map((s) => (
                  <div key={s.id} style={styles.sessionItem}>
                    <div style={styles.sessionLeft}>
                      <span style={{ fontWeight: 600 }}>{s.subject}</span>
                      <span style={{ fontSize: '0.75rem', color: '#888' }}>
                        {new Date(s.createdAt).toLocaleTimeString()} — {s.studentCount} student{s.studentCount !== 1 ? 's' : ''}
                      </span>
                    </div>
                    <div>
                      {s.isActive ? (
                        <span style={styles.activeBadge}>Active</span>
                      ) : (
                        <span style={styles.endedBadge}>Ended</span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

